validator:
function validate(input) {
  const [{ Products = [] }] = input;
  const ids = new Set();
  for (const [id, lowFats, recyclable] of Products) {
    if (id === null) return 'Every product needs a product_id.';
    if (ids.has(id)) return `product_id ${id} appears twice.`;
    ids.add(id);
    if (lowFats !== 'Y' && lowFats !== 'N') return `low_fats must be 'Y' or 'N', not ${lowFats}.`;
    if (recyclable !== 'Y' && recyclable !== 'N') return `recyclable must be 'Y' or 'N', not ${recyclable}.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = (n) => Math.floor(rand() * n);
  const count = small ? pick(9) : 2000;
  // Distinct ids drawn from a shuffled pool so they arrive in no particular order.
  const pool = Array.from({ length: small ? 12 : 4000 }, (_, i) => i);
  for (let i = pool.length - 1; i > 0; i--) { const j = pick(i + 1); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  // Some small cases lean towards one flag value so that none or all products qualify.
  const bias = small ? [0.5, 0.1, 0.9][pick(3)] : 0.5;
  const flag = () => (rand() < bias ? 'Y' : 'N');
  const Products = [];
  for (let k = 0; k < count; k++) Products.push([pool[k], flag(), flag()]);
  return [{ Products }];
}
